<?php $v=$old??$user??['active'=>1,'role'=>'cliente']; ?><section class="container section-space narrow"><a class="back-link" href="<?= url('/admin') ?>">← Volver a administración</a><div class="page-heading"><div><span class="eyebrow">ACCESO A LA PLATAFORMA</span><h1><?= $user?'Editar cuenta.':'Nueva cuenta.' ?></h1></div></div><?php if(isset($error)): ?><div class="notice error" role="alert"><?= e($error) ?></div><?php endif; ?><form class="panel stack-form" method="post" action="<?= url('/admin/usuarios'.($user?'/'.$user['id']:'')) ?>" data-submit-once><?= csrf_field() ?><div class="field"><label for="name">Nombre completo</label><input id="name" name="name" value="<?= e($v['name']??'') ?>" minlength="2" maxlength="100" required></div><div class="field"><label for="email">Correo electrónico</label><input id="email" name="email" type="email" value="<?= e($v['email']??'') ?>" maxlength="120" required></div><div class="field"><label for="role">Perfil de acceso</label><select id="role" name="role"><?php foreach(['cliente','vendedor','administrador'] as $r): ?><option value="<?= $r ?>" <?= $v['role']===$r?'selected':'' ?>><?= e(role_label($r)) ?></option><?php endforeach; ?></select></div><div class="field"><label for="password"><?= $user?'Nueva contraseña (opcional)':'Contraseña' ?></label><input id="password" name="password" type="password" autocomplete="new-password" minlength="10" maxlength="72" <?= !$user?'required':'' ?>><small>Entre 10 y 72 bytes. <?= $user?'Deja el campo vacío para conservar la actual.':'' ?></small></div><label class="check-field"><input type="checkbox" name="active" value="1" <?= $v['active']?'checked':'' ?>> Cuenta activa</label><div class="form-actions"><a class="button button-outline" href="<?= url('/admin') ?>">Cancelar</a><button class="button button-primary">Guardar cuenta</button></div></form></section>